.planner {
    position: relative;
}

.overlay {
    position: fixed;
    inset: 0;
    background: rgba(23, 32, 46, .32);
    backdrop-filter: saturate(130%) blur(2px);
    z-index: 40;
}

#pl-overlay {
  position: fixed;
  inset: 0;
  background: rgba(0,0,0,0.45);
  z-index: 9998;
}

#pl-panel {
  position: fixed;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  z-index: 9999;

  width: min(900px, calc(100vw - 32px));
  max-height: calc(100vh - 32px);
  overflow: auto;
}


.panel {
    position: fixed;
    right: 12px;
    top: 12px;
    bottom: 12px;
    width: min(540px, calc(100vw - 24px));
    background: #fff;
    border: 1px solid #e6e9ef;
    border-radius: 12px;
    box-shadow: 0 10px 30px rgba(3, 27, 78, .12);
    z-index: 41;
    padding: 14px 14px 12px;
    display: flex;
    flex-direction: column;
    gap: 12px;
}

.hdr {
    display: flex;
    align-items: flex-start;
    justify-content: space-between
}

.title {
    font: 700 18px/1.2 Inter, system-ui;
    color: #121a26;
    margin-bottom: 4px
}

.sub {
    font: 12px/1.2 Inter, system-ui;
    color: #5b6b7b
}

.iconbtn {
    border: 1px solid #e6e9ef;
    background: #fff;
    border-radius: 8px;
    padding: 6px 10px;
    cursor: pointer
}

.iconbtn:hover {
    background: #f7f9fc
}

.sect {
    border: 1px solid #eef2f6;
    border-radius: 10px;
    padding: 10px;
    display: grid;
    gap: 10px
}

.sect-h {
    font: 600 13px/1.2 Inter, system-ui;
    color: #263442
}

.grid2 {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px
}

.grid3 {
    display: grid;
    grid-template-columns: 1fr 1fr 1fr;
    gap: 12px
}

.kpis .k {
    font: 600 11px/1 Inter, system-ui;
    color: #607d8b
}

.kpis .v {
    font: 700 18px/1.2 Inter, system-ui;
    color: #1b2430;
    margin-top: 3px
}

label {
    font: 600 12px/1 Inter, system-ui;
    color: #4c5a67;
    margin-bottom: 4px;
    display: block
}

input[type="number"],
input[type="datetime-local"],
select,
textarea {
    width: 100%;
    border: 1px solid #e2e8f0;
    border-radius: 8px;
    padding: 8px 10px;
    font: 13px/1.2 Inter, system-ui;
    color: #1b2430;
    background: #fff
}

textarea {
    resize: vertical
}

.cass {
    display: grid;
    gap: 8px
}

.cass .row {
    display: grid;
    grid-template-columns: 28px 1fr auto 140px;
    gap: 10px;
    align-items: center
}

.lab {
    width: 22px;
    height: 18px;
    border-radius: 10px;
    text-align: center;
    font: 700 12px/18px Inter, system-ui;
    color: #fff
}

.lab.a {
    background: #16A34A
}

.lab.b {
    background: #F59E0B
}

.lab.c {
    background: #06B6D4
}

.lab.d {
    background: #2563EB
}

.hint {
    font: 12px/1.2 Inter, system-ui;
    color: #607d8b
}

.foot {
    display: flex;
    align-items: center;
    justify-content: space-between
}

.actions {
    display: flex;
    gap: 8px
}

.btn {
    border: 1px solid #e6e9ef;
    background: #fff;
    border-radius: 10px;
    padding: 8px 12px;
    cursor: pointer;
    font: 13px/1 Inter, system-ui;
    color: #1b2430
}

.btn:hover {
    background: #f7f9fc
}

.btn.prim {
    background: #2563EB;
    color: #fff;
    border-color: #2563EB
}

.btn.ghost {
    background: #fff;
    color: #1b2430
}

descriptor.controllerScript:
self.onInit = function () {
  const ctx = self.ctx;

  // Settings you can override from the widget Settings JSON
  const S = Object.assign({
    fallbackTarget: 2500,
    defaultVendor: "Company A",
    openOnEvent: "CIT_PLAN_REQUESTED",  // listen for Near-Empty widget broadcast
    submitEvent:  "CIT_PLAN_CREATED",   // what we emit on Submit
    stateEntityParam: "Selected_ATM",
    stateEntityType: "DEVICE",
    estDailyNotes: 800                  // used for post-load DTE if denoms missing
  }, ctx.settings || {});

  const ui = {
    overlay: document.getElementById('pl-overlay'),
    panel:   document.getElementById('pl-panel'),
    close:   document.getElementById('pl-close'),
    cancel:  document.getElementById('pl-cancel'),
    submit:  document.getElementById('pl-submit'),

    atm:     document.getElementById('pl-atm'),
    branch:  document.getElementById('pl-branch'),
    sub:     document.getElementById('pl-sub'),
    cash:    document.getElementById('pl-cash'),
    dte:     document.getElementById('pl-dte'),
    fso:     document.getElementById('pl-fso'),
    dte2:    document.getElementById('pl-dte2'),

    // cassette labels and inputs
    nowA: document.getElementById('ca-now'), tgtA: document.getElementById('ca-target'), loadA: document.getElementById('ca-load'),
    nowB: document.getElementById('cb-now'), tgtB: document.getElementById('cb-target'), loadB: document.getElementById('cb-load'),
    nowC: document.getElementById('cc-now'), tgtC: document.getElementById('cc-target'), loadC: document.getElementById('cc-load'),
    nowD: document.getElementById('cd-now'), tgtD: document.getElementById('cd-target'), loadD: document.getElementById('cd-load'),

    val: document.getElementById('pl-value'),
    window: document.getElementById('pl-window'),
    eta: document.getElementById('pl-eta'),
    vendor: document.getElementById('pl-vendor'),
    notes: document.getElementById('pl-notes')
  };

  let selected = null; // { entityType, id, name }
  let snapshot = null; // telemetry/attrs at open

  function openFor(device) {
    selected = device;
    const rows = collectLatest(); // all devices in subscription
    const row = rows.find(r => r.id === device.id);
    if (!row) { console.warn("Planner: device not in datasource", device); return; }

    snapshot = computeSnapshot(row);

    // Fill UI
    ui.atm.textContent = device.name || row.name;
    ui.branch.textContent = row.vals['branch'] || '—';
    ui.sub.textContent = `${device.id}`;
    ui.cash.textContent = fmtPct(row.vals['cash-level-pct']);
    ui.dte.textContent  = fmtDays(row.vals['cash-days-to-empty']);
    ui.fso.textContent  = row.vals['forecast-stockout-hrs'] != null ? `${Number(row.vals['forecast-stockout-hrs']).toFixed(0)} h` : '—';

    const fmtCass = (n, den) => den ? `${n} (${currency(n*den)})` : `${n}`;
    ui.nowA.textContent = fmtCass(snapshot.a.now, snapshot.a.den);
    ui.nowB.textContent = fmtCass(snapshot.b.now, snapshot.b.den);
    ui.nowC.textContent = fmtCass(snapshot.c.now, snapshot.c.den);
    ui.nowD.textContent = fmtCass(snapshot.d.now, snapshot.d.den);

    ui.tgtA.textContent = `/ ${snapshot.a.tgt}`;
    ui.tgtB.textContent = `/ ${snapshot.b.tgt}`;
    ui.tgtC.textContent = `/ ${snapshot.c.tgt}`;
    ui.tgtD.textContent = `/ ${snapshot.d.tgt}`;

    // Pre-fill loads = max(target - now, 0)
    ui.loadA.value = Math.max(snapshot.a.tgt - snapshot.a.now, 0);
    ui.loadB.value = Math.max(snapshot.b.tgt - snapshot.b.now, 0);
    ui.loadC.value = Math.max(snapshot.c.tgt - snapshot.c.now, 0);
    ui.loadD.value = Math.max(snapshot.d.tgt - snapshot.d.now, 0);

    ui.vendor.value = S.defaultVendor;
    ui.window.value = "today";
    ui.eta.value = ""; // hidden unless 'custom'

    recalc();

    ui.overlay.hidden = false;
    ui.panel.hidden = false;
  }

  function close() {
    ui.overlay.hidden = true;
    ui.panel.hidden = true;
  }

  function collectLatest() {
    const sub = ctx.defaultSubscription || {};
    const out = [];
    for (const item of (sub.data || [])) {
      const id = item?.entityId?.id || item?.entity?.id?.id || item?.datasource?.entity?.id?.id || item?.entityId;
      if (!id) continue;
      const name = item.entityName || item?.entity?.name || item?.datasource?.entityName || "device";
      const key  = item?.dataKey?.name || item?.dataKey?.label || item?.name || item?.key;
      let v;
      if (Array.isArray(item.data) && item.data.length) {
        const d = item.data[0]; v = Array.isArray(d) ? d[1] : d.value;
      } else if ("value" in item) v = item.value;

      let row = out.find(r => r.id === id);
      if (!row) { row = { id, name, vals: {} }; out.push(row); }
      row.vals[key] = v;
    }
    return out;
  }

  function computeSnapshot(r) {
    const val = k => Number(r.vals[k]);
    const attr = (k)=> Number(r.vals[k]);
    const dena = Number(r.vals['cassette-a-denomination']) || 0;
    const denb = Number(r.vals['cassette-b-denomination']) || 0;
    const denc = Number(r.vals['cassette-c-denomination']) || 0;
    const dend = Number(r.vals['cassette-d-denomination']) || 0;

    const tgt = (k, maxNow) => {
      const t = attr(k); 
      if (Number.isFinite(t) && t > 0) return t;
      return Math.max(maxNow, S.fallbackTarget);
    };

    const now = {
      a: val('cash-cassette-a-notes') || 0,
      b: val('cash-cassette-b-notes') || 0,
      c: val('cash-cassette-c-notes') || 0,
      d: val('cash-cassette-d-notes') || 0
    };
    const maxNow = Math.max(now.a, now.b, now.c, now.d, 0);

    return {
      a: { now: now.a, tgt: tgt('cassette-a-target-notes', maxNow), den: dena },
      b: { now: now.b, tgt: tgt('cassette-b-target-notes', maxNow), den: denb },
      c: { now: now.c, tgt: tgt('cassette-c-target-notes', maxNow), den: denc },
      d: { now: now.d, tgt: tgt('cassette-d-target-notes', maxNow), den: dend }
    };
  }

  function recalc() {
    const loads = {
      a: clampInt(ui.loadA.value), b: clampInt(ui.loadB.value),
      c: clampInt(ui.loadC.value), d: clampInt(ui.loadD.value)
    };

    const vals = [
      ['A', loads.a, snapshot.a.den],
      ['B', loads.b, snapshot.b.den],
      ['C', loads.c, snapshot.c.den],
      ['D', loads.d, snapshot.d.den]
    ];

    const value = vals.reduce((sum, [_, n, den]) => sum + (n * (den || 0)), 0);
    ui.val.textContent = value ? `Load value ≈ ${currency(value)}` : '—';

    // crude post-load DTE: (current notes + load notes) / estDailyNotes
    const currentSum = (snapshot.a.now + snapshot.b.now + snapshot.c.now + snapshot.d.now);
    const extra = loads.a + loads.b + loads.c + loads.d;
    const daily = S.estDailyNotes > 0 ? S.estDailyNotes : 1;
    const dte2 = (currentSum + extra) / daily;
    ui.dte2.textContent = isFinite(dte2) ? `${dte2.toFixed(1)} d` : '—';
  }

  function clampInt(x){ const n = Math.max(0, Math.floor(Number(x)||0)); return n; }
  function fmtPct(x){ x = Number(x); return isFinite(x) ? `${x.toFixed(0)}%` : '--%'; }
  function fmtDays(x){ x = Number(x); return isFinite(x) ? `${x.toFixed(1)} d` : '-- d'; }
  function currency(x){ return new Intl.NumberFormat(undefined,{style:'currency',currency:'ZAR',maximumFractionDigits:0}).format(x); }

  // Wire inputs to recalc
  ['ca-load','cb-load','cc-load','cd-load','pl-window','pl-eta','pl-vendor'].forEach(id=>{
    const el = document.getElementById(id);
    el && el.addEventListener('input', recalc);
    el && el.addEventListener('change', recalc);
  });

  // Open from broadcast (main dashboard)
  ctx.subscribeBroadcast && ctx.subscribeBroadcast(S.openOnEvent, (payload)=>{
    const device = {
      entityType: (S.stateEntityType || 'DEVICE').toUpperCase(),
      id: payload?.deviceId,
      name: payload?.assetId || ''
    };
    if (device.id) openFor(device);
  });

  //Also allow opening from state entity (if used in a dedicated state)
  //const sp = ctx.stateController.getStateParams?.() || {};
  //const stateEnt = sp[S.stateEntityParam] || sp['entityId'];
  //if (stateEnt && stateEnt.id) {
  //  openFor({ entityType: stateEnt.entityType || S.stateEntityType, id: stateEnt.id, name: stateEnt.name || '' });
  //}

  // Close + Submit
  ui.close.onclick = ui.cancel.onclick = close;

  ui.submit.onclick = function () {
    if (!selected || !snapshot) return;

    const load = {
      A: clampInt(ui.loadA.value), B: clampInt(ui.loadB.value),
      C: clampInt(ui.loadC.value), D: clampInt(ui.loadD.value)
    };

    // Pick ETA
    let etaType = ui.window.value;
    let etaIso  = null;
    if (etaType === 'custom' && ui.eta.value) {
      // keep as local ISO; let backend convert to UTC if needed
      etaIso = ui.eta.value;
    }

    const plan = {
      planId: `CIT-${Date.now().toString(36).toUpperCase()}`,
      device: selected,
      createdTs: Date.now(),
      window: etaType,
      eta: etaIso,
      vendor: ui.vendor.value || S.defaultVendor,
      loadNotes: load,
      targets: {
        A: snapshot.a.tgt, B: snapshot.b.tgt, C: snapshot.c.tgt, D: snapshot.d.tgt
      },
      denoms: {
        A: snapshot.a.den || null, B: snapshot.b.den || null, C: snapshot.c.den || null, D: snapshot.d.den || null
      },
      notes: ui.notes.value || '',
      source: 'dashboard'
    };

    // Emit for your rule chain / backend to act on
    if (ctx.broadcast) ctx.broadcast(S.submitEvent, plan);

    // Optional toast (ThingsBoard convenience)
    if (window.tbAlertSuccess) tbAlertSuccess('CIT plan submitted');

    close();
  };
};

